void unit_test_pop_successful_shrink(void) {
    DArrayStack *stack = NULL;
    int success = 0;
    int popped_value = 0;
    int initial_capacity = 4;
    int values[] = {10, 20, 30, 40};

    stack = helper_create_stack_with_values(values, 4, initial_capacity);
    TEST_ASSERT_NOT_NULL(stack);
    TEST_ASSERT_EQUAL_INT(4, stack->capacity);
    TEST_ASSERT_EQUAL_INT(3, stack->top);

    int size_before = stack_size(stack);
    TEST_ASSERT_EQUAL_INT(4, size_before);

    popped_value = pop(stack, &success);
    TEST_ASSERT_EQUAL_INT(1, success);
    TEST_ASSERT_EQUAL_INT(40, popped_value);

    int size_after = stack_size(stack);
    TEST_ASSERT_EQUAL_INT(3, size_after);
    TEST_ASSERT_EQUAL_INT(2, stack->top);

    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_pop_successful_shrink);
    return UNITY_END();
